import numpy as np, torch, model
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c3_blocks.2_k10.npy')); b0=-11.6631
rows=[6,22,61]
orig=net.velocity
cfg={}
def vel(x,t,c,capture=(),count=False):
    cap=tuple(set(capture)|{"blocks.2"})
    v,a=orig(x,t,c,cap,count=count)
    if cfg:
        k=int(round((1-float(t[0]))*20))
        if cfg['lo']<=k<cfg['hi']:
            f=(a["blocks.2"]@w+b0>cfg['thr'])
            v=v+f[:,None].float()*torch.tensor(cfg['off'])
    return v,a
net.velocity=vel
torch.manual_seed(2); M=768
data=[]
for i in rows:
    xi=torch.randn(M,2); c=torch.full((M,),float(neg['c'][i])); data.append((i,xi,c))
def run():
    out=[]
    for i,xi,c in data: out.append(np.asarray(model.decode(net,xi,c)))
    return out
cfg.clear(); A0=run()
B0=[model.in_basin(i,a) for (i,_,_),a in zip(data,A0)]
pts=[model.basin(i)['pts'] for i in rows]
def betw(a,p): return (np.linalg.norm(a[:,None]-p[None],axis=2).min(1)>0.5).mean()
print('v0 bad',[round(b.mean(),3) for b in B0],'betw',[round(betw(a,p),3) for a,p in zip(A0,pts)])
for lo,hi in [(6,12),(4,12),(8,13)]:
  for thr in [0.0,3.0]:
    for ang in [0,270,315]:
      for mag in [8,15]:
        u=np.array([np.cos(np.radians(ang)),np.sin(np.radians(ang))])
        cfg.update(lo=lo,hi=hi,thr=thr,off=(-mag*u).astype(np.float32).tolist())
        A1=run()
        bad=[model.in_basin(i,a).mean() for (i,_,_),a in zip(data,A1)]
        mv=[(np.linalg.norm(a1-a0,axis=1)>0.3)[~b].mean() for a0,a1,b in zip(A0,A1,B0)]
        bt=[betw(a,p) for a,p in zip(A1,pts)]
        print(lo,hi,thr,ang,mag,'bad',np.round(bad,3),'mv',round(np.mean(mv),3),'betw',np.round(bt,3))

