import numpy as np, torch, model
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c3_blocks.2.act_k12.npy')); b=-17.2196
xi=torch.tensor(np.load('xi_s.npy')); c=torch.tensor(np.load('c_s.npy'))
ex=[list(neg['uid']).index(u) for u in [14,52,175]]
for i in ex: bb=model.basin(i); print('eps',bb['eps'],'thr',bb['thr'])
class G:
    def __init__(s,dv,lo,hi,thr=0.): s.layer='out'; s.dv=torch.tensor(dv,dtype=torch.float32); s.lo=lo; s.hi=hi; s.thr=thr
    def fires(s,f,t):
        k=torch.round((1-t.reshape(-1))*20)
        return ((f['blocks.2.act']@w+b)>s.thr)&(k>=s.lo)&(k<s.hi)
    def contribution(s,f): return s.dv.expand(f['x'].shape[0],2)
a0=np.asarray(model.decode(net,xi,c))
def lab(a):
    out=np.zeros(len(a),bool)
    for i in ex:
        m=np.abs(c.numpy()-neg['c'][i])<0.05
        out[m]|=model.in_basin(i,a[m])
    return out
